        self.requests.try_iter().take(max).collect()
    }

    /// Every frame subscribed devices sent since the last poll.
    pub fn poll_frames(&mut self) -> Vec<SubscriberFrame> {
        self.frames.try_iter().collect()
    }

    #[must_use]
    pub fn addr(&self) -> SocketAddr {
        self.addr
    }
}

