:root {
  color-scheme: light dark;
  --bg: #fafafa;
  --fg: #1d1d1f;
  --dim: #6e6e73;
  --line: #d2d2d7;
  --card: #ffffff;
  --accent: #b45309;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1c1c1e;
    --fg: #f2f2f7;
    --dim: #98989d;
    --line: #3a3a3c;
    --card: #2c2c2e;
    --accent: #f59e0b;
  }
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.4 -apple-system, system-ui, sans-serif;
}
header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}
h1 { margin: 0; font-size: 18px; }
h2 { margin: 20px 0 6px; font-size: 13px; color: var(--dim); text-transform: uppercase; }
main { padding: 0 16px 32px; max-width: 720px; margin: 0 auto; }
.meta { color: var(--dim); font-size: 13px; }
.notice { margin: 24px 0; padding: 14px; border: 1px solid var(--line); border-radius: 10px; background: var(--card); }
.row {
  display: block;
  width: 100%;
  text-align: left;
  margin: 6px 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--card);
  color: inherit;
  font: inherit;
}
.row.waiting { border-left: 4px solid var(--accent); }
.row .name { font-weight: 600; }
pre {
  margin: 12px 0;
  padding: 12px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--card);
  font: 13px/1.4 ui-monospace, Menlo, monospace;
}
textarea {
  width: 100%;
  min-height: 72px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--card);
  color: inherit;
  font: inherit;
}
button.act {
  margin: 8px 8px 0 0;
  padding: 10px 16px;
  border: 0;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  font: inherit;
}

