#[test]
fn the_invite_is_a_url_with_the_code_key_and_id_in_its_fragment() {
    use crate::core::remote::pairing_invite;
    let id = identity();
    let url = pairing_invite(&id, "192.168.1.9:43187", "abcd2345");
    assert_eq!(
        url,
        format!(
            "https://192.168.1.9:43187/#code=ABCD2345&key={}&id={}",
            id.spki_sha256, id.server_id
        )
    );
    let v6 = pairing_invite(&id, "[fe80::1]:43187", "ABCD2345");
    assert!(v6.starts_with("https://[fe80::1]:43187/#code="), "{v6}");
    // An unbracketed literal with a port is bracketed.
    let bare = pairing_invite(&id, "fe80::1:43187", "ABCD2345");
    assert!(bare.starts_with("https://"), "{bare}");
    let v6 = pairing_invite(&id, &format!("{}", std::net::SocketAddr::from(([0; 16], 1))), "A");
    assert!(v6.starts_with("https://[::]:1/#"), "{v6}");
    assert!(!url.contains("token"));
}

